const order = {
  price: 5,
  qty: 2,
  total() {
    return this.price * this.qty;
  },
};

const reads = [];

const spy = new Proxy(order, {
  get(target, key, receiver) {
    reads.push(key);
    return Reflect.get(target, key, receiver);
  },
});

console.log(spy.total());
console.log(reads.join(","));
console.log(order.total(), reads.length);
